package dev.chyken.assembl_ar.vision;
import android.content.*;import android.content.res.*;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import dev.chyken.assembl_ar.camera.*;import org.junit.*;import org.junit.runner.RunWith;import org.opencv.android.OpenCVLoader;import org.opencv.core.*;import org.opencv.imgcodecs.Imgcodecs;import org.opencv.imgproc.Imgproc;import java.io.*;import java.util.*;import static org.junit.Assert.*;
/** Native fixtures are isolated from learner records and camera lifecycle. */
@RunWith(AndroidJUnit4.class) public final class Phase11ReferenceMatcherInstrumentedTest {
    @BeforeClass public static void initialize(){assertTrue(OpenCVLoader.initLocal());}
    @Test public void stagesLoadAllPhotosAndRecognizeHeldOutRotatedViews()throws Exception{Context app=InstrumentationRegistry.getInstrumentation().getTargetContext();AssetManager assets=app.getAssets();VisionConfig config=VisionConfig.defaults();List<ComponentReferenceSpec> all=Phase11AssetCatalog.references(assets);
        for(int stage=1;stage<=3;stage++){List<ComponentReferenceSpec> bank=new ArrayList<>();for(ComponentReferenceSpec s:all)if(Phase11AssetCatalog.eligible(Phase11AssetCatalog.referenceRole(s.getReferenceId()),stage))bank.add(s);ComponentReferenceSpec probe=bank.remove(0);
            try(ReferenceDatabase db=ReferenceDatabase.load(assets,bank,config,new File(app.getCacheDir(),"p11_native_test"));Phase11ReferenceMatcher matcher=new Phase11ReferenceMatcher(db,config)){assertEquals(bank.size(),db.size());if(stage==3)for(ReferenceDatabase.PreparedReference ref:db.preparedReferences()){
                    List<VisionPoint> c=ref.spec.getPlanarCornersNormalized();double l=c.get(0).getX()*ref.imageWidth,t=c.get(0).getY()*ref.imageHeight,r=c.get(2).getX()*ref.imageWidth,b=c.get(2).getY()*ref.imageHeight;int local=0,context=0;
                    for(KeyPoint k:ref.keypoints)if(k.pt.x>=l&&k.pt.x<=r&&k.pt.y>=t&&k.pt.y<=b)local++;else if(k.pt.x<l-(r-l)*.15||k.pt.x>r+(r-l)*.15||k.pt.y<t-(b-t)*.15||k.pt.y>b+(b-t)*.15)context++;
                    assertTrue("OLED detail must survive preparation: "+ref.spec.getReferenceId(),local>=20);assertTrue("Board context must survive preparation: "+ref.spec.getReferenceId(),context>=40);
                }Mat photo=read(assets,probe.getJpegAssetPath()),rotated=new Mat();try{double cameraScale=640.0/Math.max(photo.cols(),photo.rows());Imgproc.resize(photo,photo,new Size(),cameraScale,cameraScale,Imgproc.INTER_AREA);Core.rotate(photo,rotated,Core.ROTATE_90_CLOCKWISE);boolean found=false;for(int frame=0;frame<bank.size()*2;frame++){RecognitionResult result=matcher.inspect(rotated,frame+1,stage);assertNull(result.getPose());if(result.getPhase11Observation().accepted()){found=true;break;}}assertTrue("Held-out phase11 stage "+stage,found);}finally{photo.release();rotated.release();}}
        }
    }
    @Test public void chassisWithoutOledCannotPassInstalledDisplay()throws Exception{Context app=InstrumentationRegistry.getInstrumentation().getTargetContext();AssetManager assets=app.getAssets();List<ComponentReferenceSpec> bank=new ArrayList<>();for(ComponentReferenceSpec s:Phase11AssetCatalog.references(assets))if("assembly".equals(Phase11AssetCatalog.referenceRole(s.getReferenceId())))bank.add(s);
        try(ReferenceDatabase db=ReferenceDatabase.load(assets,bank,VisionConfig.defaults(),new File(app.getCacheDir(),"p11_native_test"));Phase11ReferenceMatcher matcher=new Phase11ReferenceMatcher(db,VisionConfig.defaults())){for(ReferenceDatabase.PreparedReference ref:db.preparedReferences()){Mat photo=read(assets,ref.spec.getJpegAssetPath());try{List<VisionPoint> roi=ref.spec.getPlanarCornersNormalized();Imgproc.rectangle(photo,new Point(roi.get(0).getX()*photo.cols(),roi.get(0).getY()*photo.rows()),new Point(roi.get(2).getX()*photo.cols(),roi.get(2).getY()*photo.rows()),new Scalar(200),-1);for(int n=0;n<bank.size();n++)assertFalse(ref.spec.getReferenceId(),matcher.inspect(photo,n+1,3).getPhase11Observation().accepted());}finally{photo.release();}}}
    }
    @Test public void preparationResumesAndWarmLibraryDoesNotRewriteDescriptors()throws Exception{Context app=InstrumentationRegistry.getInstrumentation().getTargetContext();AssetManager assets=app.getAssets();List<ComponentReferenceSpec> bank=Phase11AssetCatalog.references(assets).subList(0,3);File directory=new File(app.getCacheDir(),"p11_library_resume_test");VisionConfig config=VisionConfig.defaults();ReferenceCacheIndex index=new ReferenceCacheIndex(directory,app.getApplicationInfo().sourceDir,ReferenceDatabase.cacheRevision());ReferenceCacheIndex.install(assets,index);java.util.concurrent.atomic.AtomicBoolean active=new java.util.concurrent.atomic.AtomicBoolean(true);
        try{try{ReferenceDatabase.prepareLibrary(assets,bank,config,directory,index,active::get,(d,t)->active.set(false));fail("Expected cancellation between photos");}catch(InterruptedIOException expected){}assertTrue(index.terminal(bank.get(0),config));ReferenceDatabase.prepareLibrary(assets,bank,config,directory,index,()->true,(d,t)->{});Map<String,Long> times=new HashMap<>();for(File f:directory.listFiles())if(f.getName().endsWith(".asor"))times.put(f.getName(),f.lastModified());ReferenceDatabase.prepareLibrary(assets,bank,config,directory,index,()->true,(d,t)->{});try(ReferenceDatabase db=ReferenceDatabase.load(assets,bank,config,directory)){assertEquals(3,db.size());}for(Map.Entry<String,Long> e:times.entrySet())assertEquals(e.getValue().longValue(),new File(directory,e.getKey()).lastModified());}finally{ReferenceCacheIndex.install(assets,null);}
    }
    /** Exact tablet captures stay in diagnostics storage and never enter the reference bank. */
    @Test public void capturedOledMatchesAtCameraScaleAndMaskedDisplayDoesNot()throws Exception{
        String path=InstrumentationRegistry.getArguments().getString("phase11Frame");Assume.assumeNotNull(path);Context app=InstrumentationRegistry.getInstrumentation().getTargetContext();File frame=new File(path).getCanonicalFile(),root=app.getExternalFilesDir("measure").getCanonicalFile();assertTrue(frame.getPath().startsWith(root.getPath()+File.separator));
        List<ComponentReferenceSpec> refs=new ArrayList<>();for(ComponentReferenceSpec s:Phase11AssetCatalog.references(app.getAssets()))if("assembly".equals(Phase11AssetCatalog.referenceRole(s.getReferenceId())))refs.add(s);
        Mat image=Imgcodecs.imread(frame.getPath(),Imgcodecs.IMREAD_GRAYSCALE);assertFalse(image.empty());
        try(ReferenceDatabase db=ReferenceDatabase.load(app.getAssets(),refs,VisionConfig.defaults(),new File(app.getCacheDir(),"p11_native_test"));Phase11ReferenceMatcher matcher=new Phase11ReferenceMatcher(db,VisionConfig.defaults())){
            RecognitionResult matched=null;for(int rotation:new int[]{-1,Core.ROTATE_90_CLOCKWISE,Core.ROTATE_180}){Mat live=new Mat();try{if(rotation<0)image.copyTo(live);else Core.rotate(image,live,rotation);RecognitionResult result=null;for(int n=0;n<refs.size();n++){result=matcher.inspect(live,n+1,3);if(result.getPhase11Observation().accepted())break;}assertTrue("Actual OLED camera frame must match at rotation "+rotation,result.getPhase11Observation().accepted());if(rotation<0)matched=result;}finally{live.release();}}
            Mat missing=image.clone();MatOfPoint polygon=new MatOfPoint();try{List<Point> points=new ArrayList<>();for(VisionPoint p:matched.getProjectedCorners())points.add(new Point(p.getX(),p.getY()));polygon.fromList(points);Imgproc.fillConvexPoly(missing,polygon,new Scalar(200));for(int n=0;n<refs.size();n++)assertFalse("Board without OLED must not pass",matcher.inspect(missing,n+100,3).getPhase11Observation().accepted());}finally{missing.release();polygon.release();}
        }finally{image.release();}
    }
    private static Mat read(AssetManager assets,String path)throws IOException{try(InputStream in=assets.open(path);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] data=new byte[32768];for(int n;(n=in.read(data))!=-1;)out.write(data,0,n);MatOfByte bytes=new MatOfByte(out.toByteArray());Mat image=Imgcodecs.imdecode(bytes,Imgcodecs.IMREAD_GRAYSCALE);bytes.release();double scale=Math.min(1,1280.0/Math.max(image.cols(),image.rows()));if(scale<1)Imgproc.resize(image,image,new Size(),scale,scale,Imgproc.INTER_AREA);return image;}}
}
